 const fromPt=e=>{const r=el.getBoundingClientRect();let a=Math.atan2(e.clientX-(r.left+r.width/2),-(e.clientY-(r.top+r.height/2)))*180/Math.PI;a=clamp(a,A0,A1);hpa=980+(a-A0)/(A1-A0)*60;render()};
