 const STEPS=[['Gespräch','fog','Wir klären Ziel, Zielgruppe und Umfang.','Ziele, Beispiele, Fragen','Zuhören und einordnen'],['Angebot','cloud','Du bekommst Umfang, Preis und Zeitplan schriftlich.','Deine Freigabe','Angebot mit festem Umfang'],['Entwurf','clear','Zuerst die Ansicht fürs Handy, dann alles Größere.','Rückmeldung zum Entwurf','Entwurf mit echten Inhalten'],['Inhalte','rain','Texte und Bilder kommen zusammen.','Texte, Bilder, Logo','Struktur und Feinschliff'],['Umsetzung','wind','Aus dem Entwurf wird eine schnelle, statische Website.','Ein Blick auf die Vorschau','Bau auf einer Vorschau-Adresse'],['Prüfung','snow','Tempo, Barrierefreiheit, Formulare und Links werden gemessen.','Deine Abnahme','Messung und Gerätetest'],['Livegang','storm','Die Seite geht online, auf Wunsch mit Wartung.','Zugang zur Domain','Start, Weiterleitungen, Übergabe']];
